(()=>{'use strict';document.body.classList.add('js');const menu=document.querySelector('.menu-button'),nav=document.querySelector('.nav');const setMenu=(open)=>{nav.classList.toggle('is-open',open);menu.setAttribute('aria-expanded',String(open));menu.textContent=open?'Fechar':'Menu';};menu.addEventListener('click',()=>setMenu(menu.getAttribute('aria-expanded')!=='true'));nav.addEventListener('click',e=>{if(e.target.closest('a'))setMenu(false);});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&menu.getAttribute('aria-expanded')==='true'){setMenu(false);menu.focus();}});matchMedia('(min-width:801px)').addEventListener('change',e=>{if(e.matches)setMenu(false);});const reduce=matchMedia('(prefers-reduced-motion:reduce)');if('IntersectionObserver'in window){const observer=new IntersectionObserver(entries=>{for(const x of entries)if(x.isIntersecting){if(!reduce.matches)x.target.classList.add('reveal-running');observer.unobserve(x.target);}},{threshold:.12});document.querySelectorAll('[data-reveal]').forEach(el=>observer.observe(el));}const story=document.querySelector('[data-story]'),buttons=[...document.querySelectorAll('[data-finish]')],panels=[...document.querySelectorAll('[data-study-finish]')],status=document.querySelector('.finish-status'),index=document.querySelector('.study-index b');const keys=['silver','dark','cherry','blue'],labels=['prata','grafite','cereja','azul-claro'];let active=0,frame=0,visible=false,overrideY=null;const apply=(i,user=false)=>{if(i===active&&!user)return;active=i;panels.forEach((el,n)=>{el.classList.toggle('is-active',n===i);el.setAttribute('aria-hidden',String(n!==i));});buttons.forEach((b,n)=>b.setAttribute('aria-pressed',String(n===i)));status.textContent='Estudo em '+labels[i];index.textContent=String(i+1).padStart(2,'0');};buttons.forEach((b,i)=>b.addEventListener('click',()=>{overrideY=scrollY;apply(i,true);}));const paint=()=>{frame=0;if(!visible||reduce.matches||innerWidth<=800||document.hidden)return;if(overrideY!==null&&Math.abs(scrollY-overrideY)<120)return;overrideY=null;const rect=story.getBoundingClientRect(),range=Math.max(1,rect.height-innerHeight);apply(Math.min(3,Math.max(0,Math.floor(Math.min(1,Math.max(0,-rect.top/range))*4))));};const schedule=()=>{if(!frame&&visible&&!reduce.matches&&innerWidth>800)frame=requestAnimationFrame(paint);};if('IntersectionObserver'in window){new IntersectionObserver(entries=>{visible=entries[0].isIntersecting;if(visible)schedule();else{cancelAnimationFrame(frame);frame=0;}}).observe(story);}window.addEventListener('scroll',schedule,{passive:true});window.addEventListener('resize',schedule,{passive:true});document.addEventListener('visibilitychange',()=>{cancelAnimationFrame(frame);frame=0;if(!document.hidden)schedule();});reduce.addEventListener('change',()=>{cancelAnimationFrame(frame);frame=0;if(!reduce.matches)schedule();});window.addEventListener('pagehide',()=>{cancelAnimationFrame(frame);frame=0;});})();